export { anatomy, parts, type ScrollAreaPart } from "./scroll-area.anatomy";
export { connect } from "./scroll-area.connect";
export {
  getContentEl,
  getContentId,
  getCornerId,
  getRootId,
  getScrollbarEl,
  getScrollbarId,
  getThumbEl,
  getThumbId,
  getViewportEl,
  getViewportId,
} from "./scroll-area.dom";
export { machine } from "./scroll-area.machine";
export type {
  ResolvedScrollAreaMachineProps,
  ScrollAreaApi,
  ScrollAreaMachineProps,
  ScrollAreaOrientation,
  ScrollAreaSchema,
  ScrollAreaScrollToOptions,
  ScrollAxis,
} from "./scroll-area.types";

import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type ScrollAreaPart = "root" | "viewport" | "content" | "scrollbar" | "thumb" | "corner";

export const anatomy: Anatomy<ScrollAreaPart> = createAnatomy("scroll-area").parts(
  "root",
  "viewport",
  "content",
  "scrollbar",
  "thumb",
  "corner",
);

export const parts: Record<ScrollAreaPart, AnatomyPart> = anatomy.build();

import { dataAttr } from "../../dom/attrs";
import { resolveDir } from "../../dom/text-dir";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import type { Orientation } from "../../types";
import { roundToPrecision } from "../../utils/range";
import { parts } from "./scroll-area.anatomy";
import {
  getContentId,
  getCornerId,
  getRootId,
  getScrollbarId,
  getThumbId,
  getViewportEl,
  getViewportId,
} from "./scroll-area.dom";
import type {
  ScrollAreaApi,
  ScrollAreaSchema,
  ScrollAreaScrollToOptions,
  ScrollAxis,
} from "./scroll-area.types";

const PX_PRECISION = 2;

function axisOf(orientation: Orientation): ScrollAxis {
  return orientation === "horizontal" ? "x" : "y";
}

export function connect<T extends PropTypes>(
  service: Service<ScrollAreaSchema>,
  normalize: NormalizeProps<T>,
): ScrollAreaApi<T> {
  const { context, prop, computed, state, scope } = service;

  const overflowX = computed("overflowX");
  const overflowY = computed("overflowY");
  const scrolling = state.matches("scrolling");
  const dragging = state.matches("dragging");
  const lingering = state.matches("lingering");
  const hoverAxis = context.get("hoverAxis");
  const dragAxis = context.get("dragAxis");
  const focusable =
    context.get("viewportFocused") || ((overflowX || overflowY) && !context.get("hasFocusable"));

  const overflowAttrs = {
    "data-overflow-x": dataAttr(overflowX),
    "data-overflow-y": dataAttr(overflowY),
  };

  return {
    overflowX,
    overflowY,
    scrolling,
    dragging,

    scrollTo({ top, left }: ScrollAreaScrollToOptions): void {
      const viewport = getViewportEl(scope);
      if (viewport === null) return;
      const target: ScrollToOptions = {};
      if (top !== undefined) target.top = top;
      if (left !== undefined) {
        target.left = resolveDir(prop("dir"), viewport) === "rtl" ? -left : left;
      }
      viewport.scrollTo(target);
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        id: getRootId(scope),
        dir: prop("dir"),
        "data-orientation": prop("orientation"),
        "data-scrolling": dataAttr(scrolling),
        "data-dragging": dataAttr(dragging),
        "data-always": dataAttr(prop("always")),
        ...overflowAttrs,
      }),

    getViewportProps: (): T["element"] =>
      normalize.element({
        ...parts.viewport.attrs,
        id: getViewportId(scope),
        tabIndex: focusable ? 0 : undefined,
        role: focusable ? "region" : undefined,
        "aria-label": focusable ? prop("label") : undefined,
        "aria-labelledby": focusable ? prop("labelledBy") : undefined,
        ...overflowAttrs,
      }),

    getContentProps: (): T["element"] =>
      normalize.element({
        ...parts.content.attrs,
        id: getContentId(scope),
      }),

    getScrollbarProps: ({ orientation }: { orientation: Orientation }): T["element"] => {
      const axis = axisOf(orientation);
      return normalize.element({
        ...parts.scrollbar.attrs,
        id: getScrollbarId(scope, axis),
        "aria-hidden": "true",
        "data-orientation": orientation,
        "data-state": (axis === "x" ? overflowX : overflowY) ? "visible" : "hidden",
        "data-hovering": dataAttr(hoverAxis === axis && !lingering),
        "data-lingering": dataAttr(hoverAxis === axis && lingering),
        "data-dragging": dataAttr(dragAxis === axis),
      });
    },

    getThumbProps: ({ orientation }: { orientation: Orientation }): T["element"] => {
      const axis = axisOf(orientation);
      return normalize.element({
        ...parts.thumb.attrs,
        id: getThumbId(scope, axis),
        "data-orientation": orientation,
        style: {
          "--sui-scroll-area-thumb-size": `${roundToPrecision(
            computed(axis === "x" ? "thumbSizeX" : "thumbSizeY"),
            PX_PRECISION,
          )}px`,
          "--sui-scroll-area-thumb-offset": `${roundToPrecision(
            computed(axis === "x" ? "thumbOffsetX" : "thumbOffsetY"),
            PX_PRECISION,
          )}px`,
        },
      });
    },

    getCornerProps: (): T["element"] =>
      normalize.element({
        ...parts.corner.attrs,
        id: getCornerId(scope),
        "aria-hidden": "true",
        "data-state": computed("corner") ? "visible" : "hidden",
      }),
  };
}

import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";
import type { ScrollAxis } from "./scroll-area.types";

const COMPONENT = "scroll-area";

const ORIENTATION_OF: Readonly<Record<ScrollAxis, string>> = {
  x: "horizontal",
  y: "vertical",
};

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getViewportId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "viewport");
}

export function getContentId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "content");
}

export function getScrollbarId(scope: Scope, axis: ScrollAxis): string {
  return getPartId(scope, COMPONENT, "scrollbar", ORIENTATION_OF[axis]);
}

export function getThumbId(scope: Scope, axis: ScrollAxis): string {
  return getPartId(scope, COMPONENT, "thumb", ORIENTATION_OF[axis]);
}

export function getCornerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "corner");
}

export function readViewportMetrics(viewport: HTMLElement): {
  readonly viewportX: number;
  readonly viewportY: number;
  readonly contentX: number;
  readonly contentY: number;
  readonly offsetX: number;
  readonly offsetY: number;
} {
  return {
    viewportX: viewport.clientWidth,
    viewportY: viewport.clientHeight,
    contentX: viewport.scrollWidth,
    contentY: viewport.scrollHeight,
    offsetX: Math.abs(viewport.scrollLeft),
    offsetY: viewport.scrollTop,
  };
}

export function getViewportEl(scope: Scope): HTMLElement | null {
  return scope.getById(getViewportId(scope));
}

export function getContentEl(scope: Scope): HTMLElement | null {
  return scope.getById(getContentId(scope));
}

export function getScrollbarEl(scope: Scope, axis: ScrollAxis): HTMLElement | null {
  return scope.getById(getScrollbarId(scope, axis));
}

export function getThumbEl(scope: Scope, axis: ScrollAxis): HTMLElement | null {
  return scope.getById(getThumbId(scope, axis));
}

import { addDomEvent, isPrimaryPointer } from "../../dom/event";
import { observeAttributes, observeChildren, observeResize as onResize } from "../../dom/observers";
import { resolveDir } from "../../dom/text-dir";
import { trackDragAxis } from "../../interaction/drag-axis";
import { createMachine } from "../../machine/create-machine";
import type { Machine, MachineParams } from "../../machine/types";
import { FOCUSABLE_SELECTOR, isTabbable } from "../../nav";
import { isDev } from "../../utils/env";
import { warn } from "../../utils/invariant";
import {
  getContentEl,
  getRootId,
  getScrollbarEl,
  getThumbEl,
  getViewportEl,
  readViewportMetrics,
} from "./scroll-area.dom";
import {
  type AxisMetrics,
  dragOffset,
  overflows,
  pageOffset,
  thumbLength,
  thumbPosition,
  trackLength,
} from "./scroll-area.props";
import type { ScrollAreaSchema, ScrollAxis } from "./scroll-area.types";

type Params = MachineParams<ScrollAreaSchema>;

type Reader = Pick<Params, "context" | "prop">;

const AXES: readonly ScrollAxis[] = ["x", "y"];

const DEFAULT_HIDE_DELAY = 1000;

function disposeAll(disposers: VoidFunction[]): void {
  for (const dispose of disposers.reverse()) dispose();
}

function metricsOf({ context }: Reader, axis: ScrollAxis): AxisMetrics {
  return axis === "x"
    ? {
        viewport: context.get("viewportX"),
        content: context.get("contentX"),
        offset: context.get("offsetX"),
      }
    : {
        viewport: context.get("viewportY"),
        content: context.get("contentY"),
        offset: context.get("offsetY"),
      };
}

function hasCorner(reader: Reader): boolean {
  return (
    reader.prop("orientation") === "both" &&
    overflows(metricsOf(reader, "x")) &&
    overflows(metricsOf(reader, "y"))
  );
}

function trackOf(reader: Reader, axis: ScrollAxis): number {
  return trackLength(metricsOf(reader, axis).viewport, hasCorner(reader));
}

function setOffset({ context }: Reader, axis: ScrollAxis, offset: number): void {
  context.set(axis === "x" ? "offsetX" : "offsetY", offset);
}

function hasAccessibleName(node: HTMLElement): boolean {
  return (
    node.hasAttribute("aria-label") ||
    node.hasAttribute("aria-labelledby") ||
    node.hasAttribute("title")
  );
}

function writeScroll({ scope, context }: Params, axis: ScrollAxis, rtl: boolean): void {
  const viewport = getViewportEl(scope);
  if (viewport === null) return;
  if (axis === "y") {
    viewport.scrollTop = context.get("offsetY");
    return;
  }
  const offset = context.get("offsetX");
  viewport.scrollLeft = rtl ? -offset : offset;
}

export const machine: Machine<ScrollAreaSchema> = createMachine<ScrollAreaSchema>({
  props({ props }) {
    return {
      orientation: "vertical",
      always: false,
      ...props,
      hideDelay: Math.max(0, props.hideDelay ?? DEFAULT_HIDE_DELAY),
    };
  },

  context({ bindable }) {
    return {
      viewportX: bindable<number>(() => ({ defaultValue: 0 })),
      viewportY: bindable<number>(() => ({ defaultValue: 0 })),
      contentX: bindable<number>(() => ({ defaultValue: 0 })),
      contentY: bindable<number>(() => ({ defaultValue: 0 })),
      offsetX: bindable<number>(() => ({ defaultValue: 0 })),
      offsetY: bindable<number>(() => ({ defaultValue: 0 })),
      hoverAxis: bindable<ScrollAxis | null>(() => ({ defaultValue: null })),
      hasFocusable: bindable<boolean>(() => ({ defaultValue: false })),
      viewportFocused: bindable<boolean>(() => ({ defaultValue: false })),
      dragAxis: bindable<ScrollAxis | null>(() => ({ defaultValue: null })),
    };
  },

  computed: {
    overflowX: (reader) =>
      reader.prop("orientation") !== "vertical" && overflows(metricsOf(reader, "x")),
    overflowY: (reader) =>
      reader.prop("orientation") !== "horizontal" && overflows(metricsOf(reader, "y")),
    corner: (reader) => hasCorner(reader),
    thumbSizeX: (reader) => thumbLength(metricsOf(reader, "x"), trackOf(reader, "x")),
    thumbSizeY: (reader) => thumbLength(metricsOf(reader, "y"), trackOf(reader, "y")),
    thumbOffsetX: (reader) => thumbPosition(metricsOf(reader, "x"), trackOf(reader, "x")),
    thumbOffsetY: (reader) => thumbPosition(metricsOf(reader, "y"), trackOf(reader, "y")),
  },

  refs() {
    return { dragStart: null };
  },

  initialState() {
    return "idle";
  },

  effects: [
    "trackScroll",
    "observeResize",
    "trackFocusables",
    "trackViewportFocus",
    "warnIfAnonymous",
    "trackPointer",
  ],

  on: {
    "VIEWPORT.RESIZE": { actions: ["setMetrics"] },
    "CONTENT.FOCUSABLES": { actions: ["setFocusables"] },
    "VIEWPORT.FOCUS": { actions: ["setViewportFocus"] },
    "VIEWPORT.BLUR": { actions: ["setViewportFocus"] },
    "SCROLLBAR.POINTERENTER": { actions: ["setHovering"] },
    "SCROLLBAR.POINTERLEAVE": { actions: ["clearHovering"] },
    "THUMB.DRAG_START": { guard: "canDrag", target: "dragging", actions: ["beginDrag"] },
    "TRACK.PAGE": { actions: ["pageTrack"] },
  },

  states: {
    idle: {
      on: {
        "VIEWPORT.SCROLL": [
          { guard: "isAlways", actions: ["setOffsets"] },
          { target: "scrolling", actions: ["setOffsets"] },
        ],
        "SCROLLBAR.POINTERLEAVE": [
          { guard: "restartsHide", target: "lingering" },
          { actions: ["clearHovering"] },
        ],
      },
    },

    lingering: {
      effects: ["armHideTimer"],
      on: {
        "VIEWPORT.SCROLL": { target: "scrolling", actions: ["setOffsets", "clearHoverAxis"] },
        "SCROLLBAR.POINTERENTER": { target: "idle", actions: ["setHovering"] },
        "HIDE.TIMEOUT": { target: "idle", actions: ["clearHoverAxis"] },
      },
    },

    scrolling: {
      effects: ["armHideTimer"],
      on: {
        "VIEWPORT.SCROLL": { reenter: true, actions: ["setOffsets"] },
        "SCROLLBAR.POINTERLEAVE": [
          { guard: "restartsHide", reenter: true, actions: ["clearHovering"] },
          { actions: ["clearHovering"] },
        ],
        "HIDE.TIMEOUT": { target: "idle" },
      },
    },

    dragging: {
      on: {
        "VIEWPORT.SCROLL": { actions: ["setOffsets"] },
        "THUMB.DRAG": { actions: ["updateDrag"] },
        "THUMB.DRAG_END": [
          { guard: "isAlways", target: "idle", actions: ["endDrag"] },
          { target: "scrolling", actions: ["endDrag"] },
        ],
        "THUMB.DRAG_CANCEL": [
          { guard: "isAlways", target: "idle", actions: ["cancelDrag"] },
          { target: "scrolling", actions: ["cancelDrag"] },
        ],
      },
    },
  },

  implementations: {
    guards: {
      isAlways: ({ prop }) => prop("always"),
      restartsHide: ({ prop, context, event }) =>
        event.type === "SCROLLBAR.POINTERLEAVE" &&
        !prop("always") &&
        context.get("hoverAxis") === event.axis,
      canDrag(params) {
        const { event, state } = params;
        if (event.type !== "THUMB.DRAG_START" || state.matches("dragging")) return false;
        const metrics = metricsOf(params, event.axis);
        const track = trackOf(params, event.axis);
        return overflows(metrics) && track - thumbLength(metrics, track) > 0;
      },
    },

    actions: {
      setOffsets({ context, event }) {
        if (event.type !== "VIEWPORT.SCROLL") return;
        context.set("offsetX", event.offsetX);
        context.set("offsetY", event.offsetY);
      },

      setMetrics({ context, event }) {
        if (event.type !== "VIEWPORT.RESIZE") return;
        context.set("viewportX", event.viewportX);
        context.set("viewportY", event.viewportY);
        context.set("contentX", event.contentX);
        context.set("contentY", event.contentY);
        context.set("offsetX", event.offsetX);
        context.set("offsetY", event.offsetY);
      },

      setFocusables({ context, event }) {
        if (event.type === "CONTENT.FOCUSABLES") context.set("hasFocusable", event.has);
      },

      setViewportFocus({ context, event }) {
        if (event.type === "VIEWPORT.FOCUS") context.set("viewportFocused", true);
        else if (event.type === "VIEWPORT.BLUR") context.set("viewportFocused", false);
      },

      setHovering({ context, event }) {
        if (event.type === "SCROLLBAR.POINTERENTER") context.set("hoverAxis", event.axis);
      },

      clearHoverAxis({ context }) {
        context.set("hoverAxis", null);
      },

      clearHovering({ context, event }) {
        if (event.type === "SCROLLBAR.POINTERLEAVE" && context.get("hoverAxis") === event.axis) {
          context.set("hoverAxis", null);
        }
      },

      beginDrag({ context, refs, event }) {
        if (event.type !== "THUMB.DRAG_START") return;
        refs.set("dragStart", event.offset);
        context.set("dragAxis", event.axis);
      },

      updateDrag(params) {
        const { context, refs, event } = params;
        const axis = context.get("dragAxis");
        const start = refs.get("dragStart");
        if (event.type !== "THUMB.DRAG" || axis === null || start === null) return;
        setOffset(
          params,
          axis,
          dragOffset(start, event.position, metricsOf(params, axis), trackOf(params, axis)),
        );
      },

      endDrag(params) {
        const { context, refs, event } = params;
        const axis = context.get("dragAxis");
        const start = refs.get("dragStart");
        if (event.type === "THUMB.DRAG_END" && axis !== null && start !== null) {
          setOffset(
            params,
            axis,
            dragOffset(start, event.position, metricsOf(params, axis), trackOf(params, axis)),
          );
        }
        refs.set("dragStart", null);
        context.set("dragAxis", null);
      },

      cancelDrag(params) {
        const { context, refs } = params;
        const axis = context.get("dragAxis");
        const start = refs.get("dragStart");
        if (axis !== null && start !== null) setOffset(params, axis, start);
        refs.set("dragStart", null);
        context.set("dragAxis", null);
      },

      pageTrack(params) {
        const { event } = params;
        if (event.type !== "TRACK.PAGE") return;
        const metrics = metricsOf(params, event.axis);
        if (!overflows(metrics)) return;
        setOffset(params, event.axis, pageOffset(metrics, event.direction));
      },
    },

    effects: {
      trackScroll({ scope, send }) {
        const viewport = getViewportEl(scope);
        if (viewport === null) return;
        const win = viewport.ownerDocument.defaultView;
        const report = (): void =>
          send({
            type: "VIEWPORT.SCROLL",
            offsetX: Math.abs(viewport.scrollLeft),
            offsetY: viewport.scrollTop,
          });
        if (win === null) return addDomEvent(viewport, "scroll", report, { passive: true });
        let frame: number | null = null;
        const stop = addDomEvent(
          viewport,
          "scroll",
          () => {
            if (frame !== null) return;
            frame = win.requestAnimationFrame(() => {
              frame = null;
              report();
            });
          },
          { passive: true },
        );
        return () => {
          stop();
          if (frame !== null) win.cancelAnimationFrame(frame);
        };
      },

      observeResize({ scope, send }) {
        const viewport = getViewportEl(scope);
        if (viewport === null) return;
        const measure = (): void =>
          send({ type: "VIEWPORT.RESIZE", ...readViewportMetrics(viewport) });
        measure();
        const stops = [onResize(viewport, measure), onResize(getContentEl(scope), measure)];
        return () => {
          for (const stop of stops.reverse()) stop();
        };
      },

      trackFocusables({ scope, send }) {
        const content = getContentEl(scope);
        if (content === null) return;
        // The first tab stop settles the question: weighing every focusable costs a
        // `checkVisibility` each, on every batch of a virtualised list's rows.
        const sync = (): void =>
          send({
            type: "CONTENT.FOCUSABLES",
            has: Array.prototype.some.call(
              content.querySelectorAll(FOCUSABLE_SELECTOR),
              isTabbable,
            ),
          });
        sync();
        return observeChildren(content, sync, [
          "tabindex",
          "disabled",
          "hidden",
          "inert",
          "class",
          "style",
        ]);
      },

      trackViewportFocus({ scope, send }) {
        const viewport = getViewportEl(scope);
        if (viewport === null) return;
        const doc = viewport.ownerDocument;
        const win = doc.defaultView;
        // The viewport's own root, not the document: inside a shadow root the
        // document's active element is the host. A detached node has no root
        // that knows an active element.
        const isActive = (): boolean => {
          const root = viewport.getRootNode() as Partial<DocumentOrShadowRoot>;
          return root.activeElement === viewport;
        };
        let observer: MutationObserver | null = null;
        const release = (): void => {
          observer?.disconnect();
          observer = null;
        };
        const lose = (): void => {
          release();
          send({ type: "VIEWPORT.BLUR" });
        };
        // Firefox and WebKit send no `blur` when a focused node leaves the
        // document: while the viewport holds the focus, every batch of mutations
        // asks whether it still does. Each shadow root up to the document is
        // observed, since a mutation does not cross that boundary.
        const hold = (): void => {
          send({ type: "VIEWPORT.FOCUS" });
          if (observer !== null || win === null) return;
          const watcher = new win.MutationObserver(() => {
            if (!isActive()) lose();
          });
          let node: Node = viewport;
          for (;;) {
            const root = node.getRootNode();
            if (root.nodeType !== 11 || !("host" in root)) break;
            watcher.observe(root, { childList: true, subtree: true });
            node = (root as ShadowRoot).host;
          }
          watcher.observe(doc.documentElement, { childList: true, subtree: true });
          observer = watcher;
        };
        if (isActive()) hold();
        const stops = [
          addDomEvent(viewport, "focus", hold),
          addDomEvent(viewport, "blur", () => {
            if (!isActive()) lose();
          }),
        ];
        return () => {
          for (const stop of stops.reverse()) stop();
          release();
        };
      },

      warnIfAnonymous({ scope }) {
        const viewport = getViewportEl(scope);
        if (viewport === null || !isDev()) return;
        let warned = false;
        const check = (): void => {
          if (warned || viewport.getAttribute("tabindex") !== "0" || hasAccessibleName(viewport)) {
            return;
          }
          warned = true;
          warn(
            true,
            "a scroll-area takes focus with no accessible name — give it a `label` or a `labelledBy`",
          );
        };
        check();
        return observeAttributes(viewport, ["tabindex"], check);
      },

      trackPointer(params) {
        const { scope, prop, context, send, state } = params;
        const bound = new Map<
          ScrollAxis,
          { bar: HTMLElement | null; thumb: HTMLElement | null; stop: VoidFunction }
        >();

        const bind = (
          axis: ScrollAxis,
          bar: HTMLElement,
          thumb: HTMLElement | null,
        ): VoidFunction => {
          const disposers: VoidFunction[] = [];
          disposers.push(
            addDomEvent(bar, "pointerenter", () => send({ type: "SCROLLBAR.POINTERENTER", axis })),
            addDomEvent(bar, "pointerleave", () => send({ type: "SCROLLBAR.POINTERLEAVE", axis })),
          );

          if (thumb === null) return () => disposeAll(disposers);

          const onThumbSpan = (event: PointerEvent): boolean => {
            const box = thumb.getBoundingClientRect();
            return axis === "y"
              ? event.clientY >= box.top && event.clientY <= box.bottom
              : event.clientX >= box.left && event.clientX <= box.right;
          };

          disposers.push(
            addDomEvent(bar, "pointerdown", (event: PointerEvent) => {
              if (!isPrimaryPointer(event)) return;
              if (event.pointerType === "mouse") event.preventDefault();
              if (onThumbSpan(event)) return;
              const box = thumb.getBoundingClientRect();
              const before = axis === "y" ? event.clientY < box.top : event.clientX < box.left;
              const mirrored = axis === "x" && resolveDir(prop("dir"), bar) === "rtl";
              send({ type: "TRACK.PAGE", axis, direction: before !== mirrored ? -1 : 1 });
              writeScroll(params, axis, mirrored);
            }),
          );

          let active = false;
          let rtl = false;
          disposers.push(
            // No `dir`: the root wears `dir={prop("dir")}`, and the gesture reads
            // what the bar resolves when it starts, so a direction changed at
            // runtime is the one a drag follows.
            trackDragAxis(bar, {
              axis: axis === "x" ? "inline" : "block",
              canStart: onThumbSpan,
              onDragStart: (event) => {
                rtl = axis === "x" && resolveDir(prop("dir"), bar) === "rtl";
                send({
                  type: "THUMB.DRAG_START",
                  axis,
                  offset: context.get(axis === "x" ? "offsetX" : "offsetY"),
                });
                active = state.matches("dragging");
                if (!active) return;
                send({ type: "THUMB.DRAG", position: event.position });
                writeScroll(params, axis, rtl);
              },
              onDrag: (event) => {
                if (!active) return;
                send({ type: "THUMB.DRAG", position: event.position });
                writeScroll(params, axis, rtl);
              },
              onDragEnd: (event) => {
                if (!active) return;
                active = false;
                send({ type: "THUMB.DRAG_END", position: event.position });
                writeScroll(params, axis, rtl);
              },
              onDragCancel: () => {
                if (!active) return;
                active = false;
                send({ type: "THUMB.DRAG_CANCEL" });
                writeScroll(params, axis, rtl);
              },
            }),
          );
          return () => disposeAll(disposers);
        };

        // A bar or a thumb can arrive, leave or be replaced after the start
        // (`orientation` changed at runtime): each axis is bound to the nodes
        // that exist now, and rebound when they change.
        const sync = (): void => {
          for (const axis of AXES) {
            const bar = getScrollbarEl(scope, axis);
            const thumb = getThumbEl(scope, axis);
            const current = bound.get(axis);
            if (current !== undefined && current.bar === bar && current.thumb === thumb) continue;
            current?.stop();
            bound.delete(axis);
            if (bar !== null) bound.set(axis, { bar, thumb, stop: bind(axis, bar, thumb) });
          }
        };
        sync();

        const root = scope.getById(getRootId(scope));
        const viewport = getViewportEl(scope);
        const stopObserving = observeChildren(root, (_, records) => {
          if (records.every((record) => viewport?.contains(record.target) === true)) return;
          sync();
        });

        return () => {
          stopObserving();
          for (const { stop } of bound.values()) stop();
          bound.clear();
        };
      },

      armHideTimer({ prop, send }) {
        const timer = setTimeout(() => send({ type: "HIDE.TIMEOUT" }), prop("hideDelay"));
        return () => clearTimeout(timer);
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, Orientation } from "../../types";

export type ScrollAreaOrientation = Orientation | "both";

export type ScrollAxis = "x" | "y";

export interface ScrollAreaMachineProps {
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  /** Which bars are drawn; the sheet hides the overflow of an axis with no bar. Defaults to `vertical`. */
  readonly orientation?: ScrollAreaOrientation | undefined;
  /** Keeps the bars visible instead of letting them fade after a scroll. */
  readonly always?: boolean | undefined;
  /** How long the bars stay up after the last scroll, in ms. */
  readonly hideDelay?: number | undefined;
  readonly label?: string | undefined;
  readonly labelledBy?: string | undefined;
}

export interface ResolvedScrollAreaMachineProps extends ScrollAreaMachineProps {
  readonly orientation: ScrollAreaOrientation;
  readonly always: boolean;
  readonly hideDelay: number;
}

export interface ScrollAreaScrollToOptions {
  /** Distance from the block start, in px. */
  readonly top?: number | undefined;
  /** Distance from the inline start, in px, whichever way the line runs. */
  readonly left?: number | undefined;
}

export interface ScrollAreaSchema extends MachineSchema {
  state: "idle" | "scrolling" | "lingering" | "dragging";
  props: ResolvedScrollAreaMachineProps;
  context: {
    viewportX: number;
    viewportY: number;
    contentX: number;
    contentY: number;
    /** Distance from the inline start: RTL is folded into the same `0..max` range. */
    offsetX: number;
    offsetY: number;
    hoverAxis: ScrollAxis | null;
    hasFocusable: boolean;
    viewportFocused: boolean;
    dragAxis: ScrollAxis | null;
  };
  computed: {
    overflowX: boolean;
    overflowY: boolean;
    corner: boolean;
    thumbSizeX: number;
    thumbSizeY: number;
    thumbOffsetX: number;
    thumbOffsetY: number;
  };
  refs: {
    dragStart: number | null;
  };
  event:
    | {
        type: "VIEWPORT.SCROLL";
        offsetX: number;
        offsetY: number;
      }
    | {
        type: "VIEWPORT.RESIZE";
        viewportX: number;
        viewportY: number;
        contentX: number;
        contentY: number;
        offsetX: number;
        offsetY: number;
      }
    | { type: "CONTENT.FOCUSABLES"; has: boolean }
    | { type: "VIEWPORT.FOCUS" }
    | { type: "VIEWPORT.BLUR" }
    | { type: "SCROLLBAR.POINTERENTER"; axis: ScrollAxis }
    | { type: "SCROLLBAR.POINTERLEAVE"; axis: ScrollAxis }
    | { type: "THUMB.DRAG_START"; axis: ScrollAxis; offset: number }
    | { type: "THUMB.DRAG"; position: number }
    | { type: "THUMB.DRAG_END"; position: number }
    | { type: "THUMB.DRAG_CANCEL" }
    | { type: "TRACK.PAGE"; axis: ScrollAxis; direction: 1 | -1 }
    | { type: "HIDE.TIMEOUT" };
  action:
    | "setOffsets"
    | "setMetrics"
    | "setFocusables"
    | "setViewportFocus"
    | "setHovering"
    | "clearHovering"
    | "clearHoverAxis"
    | "beginDrag"
    | "updateDrag"
    | "endDrag"
    | "cancelDrag"
    | "pageTrack";
  guard: "isAlways" | "canDrag" | "restartsHide";
  effect:
    | "trackScroll"
    | "observeResize"
    | "trackFocusables"
    | "trackViewportFocus"
    | "warnIfAnonymous"
    | "trackPointer"
    | "armHideTimer";
}

export interface ScrollAreaApi<T extends PropTypes = PropTypes> {
  readonly overflowX: boolean;
  readonly overflowY: boolean;
  readonly scrolling: boolean;
  readonly dragging: boolean;
  scrollTo(options: ScrollAreaScrollToOptions): void;
  getRootProps(): T["element"];
  getViewportProps(): T["element"];
  getContentProps(): T["element"];
  getScrollbarProps(options: { orientation: Orientation }): T["element"];
  getThumbProps(options: { orientation: Orientation }): T["element"];
  getCornerProps(): T["element"];
}

import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import {
  ScrollAreaContent,
  ScrollAreaCorner,
  ScrollAreaRoot,
  ScrollAreaScrollbar,
  ScrollAreaThumb,
  ScrollAreaViewport,
  type UseScrollAreaProps,
} from "./scroll-area";

export interface ScrollAreaParts {
  readonly viewport?: Omit<PartProps<"div">, "id" | "ref"> | undefined;
  readonly content?: Omit<PartProps<"div">, "id" | "ref"> | undefined;
  readonly scrollbar?: Omit<PartProps<"div">, "id" | "ref"> | undefined;
  readonly thumb?: Omit<PartProps<"div">, "id" | "ref"> | undefined;
  readonly corner?: Omit<PartProps<"div">, "id" | "ref"> | undefined;
}

export interface ScrollAreaComposedProps
  extends UseScrollAreaProps,
    Omit<PartProps<"div", UseScrollAreaProps>, "children"> {
  readonly children?: ReactNode;
  readonly parts?: ScrollAreaParts | undefined;
}

export function ScrollArea(props: ScrollAreaComposedProps): ReactNode {
  const { children, parts, ...root } = props;
  const vertical = root.orientation !== "horizontal";
  const horizontal = root.orientation === "horizontal" || root.orientation === "both";

  return (
    <ScrollAreaRoot {...root}>
      <ScrollAreaViewport {...parts?.viewport}>
        <ScrollAreaContent {...parts?.content}>{children}</ScrollAreaContent>
      </ScrollAreaViewport>
      {vertical ? (
        <ScrollAreaScrollbar orientation="vertical" {...parts?.scrollbar}>
          <ScrollAreaThumb orientation="vertical" {...parts?.thumb} />
        </ScrollAreaScrollbar>
      ) : null}
      {horizontal ? (
        <ScrollAreaScrollbar orientation="horizontal" {...parts?.scrollbar}>
          <ScrollAreaThumb orientation="horizontal" {...parts?.thumb} />
        </ScrollAreaScrollbar>
      ) : null}
      {root.orientation === "both" ? <ScrollAreaCorner {...parts?.corner} /> : null}
    </ScrollAreaRoot>
  );
}

